{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Sacubitril absolute oral bioavailability was 60% in healthy subjects, well above the 20% threshold."
    },
    {
      "card_ids": ["C24"],
      "claim": "Tianeptine absolute oral bioavailability averaged about 99% in healthy young subjects, strongly supporting high bioavailability."
    },
    {
      "card_ids": ["C28"],
      "claim": "Idasanutlin absolute bioavailability was 40.1% in patients with solid tumors, above the threshold; a lower fed-state MBP record is less condition-matched and does not overturn this."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All ten evidence molecules support high oral bioavailability at the F>=20% threshold, with assay-transfer scores around 0.93-0.94. Numeric absolute estimates range from about 34% to 99%; the only sub-threshold record (C06) is from an altered fed-state MBP formulation and is outweighed by the ordinary-condition absolute estimate (C28).",
  "evidence_gaps": [
    "One idasanutril record (C06) reported 18.7% under fed-state MBP conditions, but it is less condition-matched than the ordinary absolute estimate (C28) and was not used for the molecule-level direction."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C05", "C24", "C28"],
  "revision_action": "initial",
  "supportive_card_ids": ["C05", "C24", "C28"]
}

